// Uma linha por empresa, com os campos planos (pronta para planilha, banco ou o próximo passo)
const empresas = $input.all().flatMap((i) => i.json.dados || []);
return empresas.map((e) => {
  const telefone = e.telefones.find((t) => t.principal) || e.telefones[0];
  return {
    json: {
      empresa_id: e.id,
      nome: e.nome,
      razao_social: e.razao_social,
      nome_fantasia: e.nome_fantasia,
      tipo_documento: e.tipo_documento,
      documento: e.documento,
      status: e.status ? e.status.nome : null,
      status_chave: e.status ? e.status.chave_sistema : null,
      tags: e.tags.map((t) => t.nome).join(', '),
      responsavel: e.responsavel.nome,
      responsavel_email: e.responsavel.email,
      vertical: e.vertical ? e.vertical.nome : null,
      telefone: telefone ? telefone.numero : null,
      website: e.website,
      municipio: e.endereco.municipio,
      uf: e.endereco.uf,
      ultimo_contato_em: e.ultimo_contato_em,
      proxima_atividade_em: e.proxima_atividade_em,
      criado_em: e.criado_em,
      atualizado_em: e.atualizado_em,
    },
  };
});

